package com.dsaroadmap.controller;
import com.dsaroadmap.dto.ApiDtos.*;import com.dsaroadmap.service.AdminService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin")public class AdminController{private final AdminService admin;public AdminController(AdminService admin){this.admin=admin;}@GetMapping("/dashboard")DashboardStats dashboard(){return admin.dashboard();}@PostMapping("/concepts")@ResponseStatus(HttpStatus.CREATED)ConceptSummary createConcept(@Valid@RequestBody ConceptRequest r){return admin.createConcept(r);}@PutMapping("/concepts/{id}")ConceptSummary updateConcept(@PathVariable Long id,@Valid@RequestBody ConceptRequest r){return admin.updateConcept(id,r);}@DeleteMapping("/concepts/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void deleteConcept(@PathVariable Long id){admin.deleteConcept(id);}@PostMapping("/problems")@ResponseStatus(HttpStatus.CREATED)ProblemDetail createProblem(@Valid@RequestBody ProblemRequest r){return admin.createProblem(r);}@PutMapping("/problems/{id}")ProblemDetail updateProblem(@PathVariable Long id,@Valid@RequestBody ProblemRequest r){return admin.updateProblem(id,r);}@DeleteMapping("/problems/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void deleteProblem(@PathVariable Long id){admin.deleteProblem(id);}}
